package com.devplatform.webhooks.consumer;

import com.devplatform.webhooks.entity.WebhookSubscription;
import com.devplatform.webhooks.event.OutboundWebhookEvent;
import com.devplatform.webhooks.repository.WebhookSubscriptionRepository;
import com.devplatform.webhooks.service.WebhookDispatcher;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.messaging.handler.annotation.Payload;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Component;

@Component
public class WebhookDeliveryConsumer {

    private static final Logger log = LoggerFactory.getLogger(WebhookDeliveryConsumer.class);
    private final WebhookSubscriptionRepository subscriptionRepository;
    private final WebhookDispatcher dispatcher;

    public WebhookDeliveryConsumer(WebhookSubscriptionRepository subscriptionRepository, WebhookDispatcher dispatcher) {
        this.subscriptionRepository = subscriptionRepository;
        this.dispatcher = dispatcher;
    }

    @KafkaListener(topics = "webhook-outbound-events", groupId = "webhook-dispatcher")
    public void deliverWebhook(@Payload OutboundWebhookEvent event) {
        WebhookSubscription subscription = subscriptionRepository.findById(event.getSubscriptionId())
                .orElseThrow(() -> new IllegalArgumentException("Subscription not found: " + event.getSubscriptionId()));
        if (!subscription.getWorkspaceId().equals(event.getSourceWorkspaceId())) {
            log.error("BOLA detected: Event workspace {} does not match subscription owner {}", event.getSourceWorkspaceId(), subscription.getWorkspaceId());
            throw new AccessDeniedException("Subscription workspace mismatch");
        }
        dispatcher.sendHttpNotification(subscription.getTargetUrl(), subscription.getSecretKey(), event.getPayloadJson());
    }
}
